import{C as i,c as p}from"./dom-6kYVTdCz.js";import{b as x,c as n,t}from"./header-CxiiZK_8.js";const S={"ne.character.awareness.why":"notices what it is doing about a beat after doing it","ne.character.control.why":"branches grow toward attention, not under command","ne.character.endurance.why":"burns bright and wide, not long — breadth is bought with open threads","ne.character.precision.why":"provisional by design: half-grown branches, held loosely on purpose","ne.character.speed.why":"forks arrive mid-thought — the divergence itself is nearly free","ne.energy.recovery.auxiliary":"Clean recovery once the options have been handed to the judge.","ne.energy.recovery.dominant":"Refills partly during use — every branch that takes pays a little back.","ne.energy.recovery.inferior":"The hangover shelf: ~30 min where the whole system runs dim and the catastrophes keep replaying.","ne.energy.recovery.shadow":"Incomplete — some of the charge simply does not come back today.","ne.energy.recovery.tertiary":"Slower: the brainstorm has to actually be put down first.","ne.feeder.fe":{figure:"The tree leans toward wherever the light of attention falls.",mechanism:"The ENTP loop, with Ti cut out: Fe — extraverted feeling — supplies the judgment of the room. Branches that get a reaction grow; branches that land flat are dropped mid-sentence. Breadth becomes performance, checked against applause and never against coherence — charming at velocity, hollow at the centre.",pair:"the ENTP Ne–Fe loop",provenance:"community",warn:"Loop coupling: extraverted judging feeding extraverted perception — no inner check."},"ne.feeder.fi":{figure:"Branches aligned with the core glow rose and stay.",mechanism:"Fi — introverted feeling — weighs every branch for whether it matters: those aligned with what is loved persist, and the merely clever wither on schedule. The tree grows lopsided toward what the person cares about — fewer directions, held longer, abandoned only when the value underneath them moves.",pair:"the ENFP · INFP coupling",provenance:"myers"},"ne.feeder.si":{figure:"The branches come out stunted and curl back toward the trunk.",mechanism:"Si — introverted sensing — floods Ne with precedent: how it went before, how it is always done — and nothing sorts any of it, because both functions gather and neither judges. These two also sit on the same axis: what one calls possibility, the other calls a departure from the file. Real stacks alternate perceiving and judging for exactly this reason.",pair:"perception feeding perception",provenance:"myers",warn:"Unstable coupling: perception feeding perception, with nothing judging either."},"ne.feeder.te":{figure:"Growth hugs the rim while the centre hollows.",mechanism:"The ENFP loop, with Fi cut out: Te — extraverted thinking — supplies judgment, but only about action. Every branch converts to a project the moment it sprouts, launched half-grown; nothing asks whether any of it matters, because the function that would ask was skipped. Velocity climbs, and the shelf of abandoned starts fills.",pair:"the ENFP Ne–Te loop",provenance:"community",warn:"Loop coupling: extraverted judging feeding extraverted perception — no inner check."},"ne.feeder.ti":{figure:"Watch the clean cuts — snipped shoots falling away as the survivors thicken.",mechanism:"Ti — introverted thinking — sits inside the loop and load-tests every branch as it grows: inconsistent ones are cut early, and the survivors grow long chains of implication that can be defended for an hour. Fewer live branches than raw divergence, each one load-bearing. The debater's tree: breadth pruned into arguments.",pair:"the ENTP · INTP coupling",provenance:"myers"},"ne.fieldNotes.mirror":{figure:"The same violet, run through the funnel in opposite directions.",mechanismHtml:"Same element, opposite attitude — the funnel reversed. <strong>Ne</strong> takes one input and fans it outward into many futures, all live at once, all cheap to hold, none of them chosen — range purchased with commitment. <strong>Ni</strong> runs the other way: many inputs funnelled into one future that arrives whole, certain, and unable to show its work. One engine bets on breadth and pays in open threads; the other bets on depth and pays in revision.",provenance:"jung"},"ne.fieldNotes.mirrorLink":"Visit the other end of the funnel →","ne.fieldNotes.vignette.fencedMeadow":{figure:"A meadow in bloom, fenced.",kind:"as a tertiary",mechanism:"Tertiary Ne in an ESTJ or ESFJ: divergence on a leash. In the planning meeting it is a genuine asset — three workable variants, one clever contingency, produced on schedule and visibly enjoyed. Then execution starts, the gate closes, and the same person who generated the options becomes the one who rules further options out of order. The branching is real; it is simply not allowed to touch anything load-bearing.",provenance:"grant",title:"The Fenced Meadow"},"ne.fieldNotes.vignette.grip":{figure:"The bloom inverts into an audit.",kind:"the grip",mechanism:"An ENTP past the end of their reserves stops generating and floods into inferior Si — suddenly cataloguing old mistakes in forensic detail, auditing every bodily signal, eating the same comfort food in front of a show they have seen nine times. Not a personality change: a low-capacity seat taking a dominant-sized flood.",provenance:"quenk",title:"The Grip"},"ne.fieldNotes.vignette.loop":{figure:"Rim-bright, centre-hollow.",kind:"the loop",mechanism:"Under stress, an ENFP's dominant Ne pairs with tertiary Te — both facing outward, with Fi's quiet question, does this actually matter to me?, cut out between them. The idea becomes a project with a name and a logo inside an hour, ships half-grown, and joins the shelf by week three, because the function that would have vetoed it was never consulted.",provenance:"community",title:"The Loop"},"ne.fieldNotes.vignette.mistakenForSe":{figure:"One is in the room; the other is in the room next door that does not exist yet.",kind:"the misread",mechanism:'Both read as "spontaneous," so the two extraverted perceivers get swapped constantly. The tell is what the spontaneity is aimed at. Se wants the actual texture of the actual moment — this wave, this crowd, this bike at this speed. Ne wants the adjacent possible, and will cheerfully talk through the entire concert about what the venue could become.',provenance:"community",title:"Mistaken for Se"},"ne.fieldNotes.vignette.neverFinish":{figure:"The map was the product; the shelf is the exhaust.",kind:"the accusation",mechanism:"The shelf of abandoned projects is real, and so is the misdiagnosis. Ne's output is not unfinished things; it is finished divergence — the value was extracted the moment the possibility space was mapped, and what the accusation prices at zero is every idea the accuser is currently executing that arrived through this function. The cost is real and worth naming; calling it laziness names the wrong line item.",provenance:"community",title:'"You Never Finish Anything"'},"ne.fieldNotes.vignette.signedContract":{figure:"Step nine works by not being looked at.",kind:"the wrong instrument",mechanism:"There are rooms where the option space is supposed to be zero: the signed contract, the safety checklist, the surgical protocol. Ne in these rooms keeps seeing the better variant — and here, uniquely, noticing possibilities is itself the hazard, because the checklist works precisely by not being reconsidered at step nine. Knowing which rooms those are is not Ne's job; that is what the judging partner in the stack is for.",provenance:"currents",title:"The Signed Contract"},"ne.fieldNotes.vignette.whiteboard":{figure:"Eleven branches, all lit; the counter is the story.",kind:"field sighting",mechanism:"Ten minutes into the meeting the board holds eleven directions, four of them good, and the Ne-dominant who produced them is delighted with all eleven. Asked to pick one, they visibly deflate — generating options and closing them are different operations, and only one of them is this function's job.",provenance:"community",title:"The Whiteboard"},"ne.hero.heading":"The Divergence of {fn}","ne.hero.subtitle":"One stimulus, a tree of possibility erupting from it — every branch forking again before the last has finished growing, and the brightest sparks escaping the chamber entirely.","ne.hero.tag":"extraverted intuition","ne.lab.btn.confine.label":"The Procedure","ne.lab.btn.confine.sub":"fully specified · zero degrees of freedom","ne.lab.btn.graft.label":"Cross-Pollination","ne.lab.btn.graft.sub":"collide two foreign domains → hybrid idea","ne.lab.btn.prune.label":"Forced Convergence","ne.lab.btn.prune.sub":'"pick one. now. in writing."',"ne.lab.btn.riff.label":"Riff Session","ne.lab.btn.riff.sub":'a live partner keeps saying "yes, and—"',"ne.lab.btn.scatter.label":"Another New Project","ne.lab.btn.scatter.sub":"abandon the tree → plant a thrilling new one","ne.lab.meter.pleasure":"Pleasure","ne.lab.meter.stress":"Stress","ne.lab.narration.confine":{figure:"The tree espaliers to the corridor, every crossing branch clipped; the faint dashed flickers outside the box are escape fantasies.",mechanism:"The procedure: fully specified, zero degrees of freedom. The generating never stops — it just stops being allowed to keep what it makes.",provenance:"currents"},"ne.lab.narration.confine2":{figure:"The bloom on release is instant.",mechanism:"Notice the stress meter: it ground upward the whole time instead of spiking, and it is still climbing. This is the expensive way to get compliance from an Ne-heavy person — the work gets done, at a cost invisible to whoever wrote the checklist. The release when the template lifts is real; it is also why the next confinement is harder.",provenance:"currents"},"ne.lab.narration.graft":{figure:"One branch arcs across the gap; the colour that erupts at the junction belongs to neither parent.",mechanism:"Two domains that have never met, growing separately — then a single connection between them takes hold. What grows at the junction could not have come from either domain alone, and it grows faster than both.",provenance:"currents"},"ne.lab.narration.graft2":{figure:"The hybrid keeps growing after both parents have slowed.",mechanism:"This is the payment Ne works for — not novelty for its own sake, but recombination. Everything genuinely new this function makes is made this way, out of at least two old things.",provenance:"currents"},"ne.lab.narration.hover":"You have the branch point. Wherever you sweep, the tree grows toward your attention — possibilities are cheap, instant, and yours. Notice they fork before you have finished looking at them: this engine does not wait for permission.","ne.lab.narration.intro":"The engine runs unattended: stimuli drift in through the gap, every arrival forks into branches, and branches fork again before the first ones have finished growing.","ne.lab.narration.introHintCoarse":"Drag a finger across the chamber to branch by hand — or run a scenario below and watch the telemetry answer.","ne.lab.narration.introHintFine":"Sweep your cursor across the chamber to branch by hand — or run a scenario below and watch the telemetry answer.","ne.lab.narration.prune":{figure:"The cut runs in a wave from the tips inward, and the survivor thickens into a stem.",mechanism:'"Pick one. Now. In writing." Commitment costs a divergence engine every living branch but one — and note which one survives: the branch that happened to be brightest at the moment of the demand. Not the best one. The brightest one.',provenance:"currents"},"ne.lab.narration.prune2":{figure:"The stump is already sprouting.",mechanism:"The closed-thread counter just moved — the only number on this page that force ever moves. Ne does not converge on its own; it gets converged, from outside. The regrowth is the resilience, and also the problem: next deadline, the wave comes again.",provenance:"currents"},"ne.lab.narration.riff":{figure:"Every response lands on a growing tip and forks it on contact.",mechanism:'A live partner saying "yes, and—" converts outside stimulation into breadth at almost no cost: stress drains while output doubles. Ne does not brainstorm well alone in a quiet room. The quiet room was the constraint.',provenance:"currents"},"ne.lab.narration.riff2":{figure:"A chamber full of live branches, none of them chosen.",mechanism:"Count what the session produced: breadth, novelty, a room full of live options — and zero decisions. That is not a failure; it is what the session is for. The mistake is scheduling a riff and expecting a verdict — verdicts are a judging function's output, and there is none in this loop.",provenance:"currents"},"ne.lab.narration.scatter":{figure:"The old tree greys into a husk the moment the new seed lands; watch the open-thread counter, not the bloom.",mechanism:"A new idea — genuinely thrilling, and the pleasure is real; nothing here is faked. But everything the old project was holding is still open. It just stopped being lit.",provenance:"currents"},"ne.lab.narration.scatter2":{figure:"The husks at the rim keep their threads: grey debt, still counted.",mechanism:"The graveyard grows by one, and the fresh start feels like progress while the total only climbs. Somewhere in that grey is a branch somebody else will grow to completion in three years — and it will be called their idea, correctly.",provenance:"currents"},"ne.lab.state.equilibrium":"Open Equilibrium","ne.lab.state.flow":"Generative Flow","ne.lab.state.pruned":"Convergence Distress","ne.lab.state.scattered":"Overextended","ne.lab.state.starved":"Novelty Starvation","ne.lab.telemetry.breadth":"Breadth","ne.lab.telemetry.cogState":"Cognitive state","ne.lab.telemetry.threads":"Open threads","ne.meta.title":"Ne — Extraverted Intuition · CURRENTS","ne.slot.auxiliary":{example:"An INFP stuck on a decision asks for possibilities and gets six, one of which is the one.",figure:"A four-fifths tree that grows toward the question it was asked.",mechanism:"In the second seat, Ne works for a dominant judging function: the framework or the conviction hands it problems, and it returns options — possible causes, possible framings, possible lives. Narrower than a first-seat spray, easier to stop, and likelier to hand the good branch over than to keep growing it for its own sake.",provenance:"myers"},"ne.slot.critical":{example:"An ENFJ, mid-success, spends an evening on the life they would have had in the city they left at 24.",figure:"Grey branches sketched over the trunk of what was actually built.",mechanism:"In the sixth seat, Ne turns inward as a heckler of roads not taken: you never considered the other offer, the other city, the other life. The audits are sporadic, harsh, and aimed at decisions already made and unmakeable — inventory without options.",provenance:"beebe"},"ne.slot.demon":{example:"Mid-celebration, an ESFP is ambushed by every way this good thing could be taken away, and goes quiet.",figure:"An inverted bloom: branches growing in at the trunk.",mechanism:"The eighth seat runs rarest and worst. When it erupts, possibility itself turns hostile: the vivid present is suddenly ringed by everything that could go wrong with it — all at once, none of it actionable, aimed at whatever is currently loved. It is the least practised seat in the stack, not a forecast.",provenance:"beebe"},"ne.slot.dominant":{example:"Ten minutes into the meeting the whiteboard holds eleven directions, four of them good.",figure:"CURRENTS draws this as a full bloom — branches forking again before the last fork has finished growing.",mechanism:"In the first seat, Ne generates continuously and at almost no cost: a fact arrives and is already three analogies and a plan, none finished, all live. The strain is never producing options — it is being asked to stop. The price is open threads: breadth is bought with things left running.",provenance:"myers"},"ne.slot.inferior":{example:"The night before the move, an ISTJ lists nineteen things that could go wrong with the van alone.",figure:"A small tree that only blooms grey — every branch a hazard sign.",mechanism:"In the fourth seat, possibility mostly registers as threat. The proven way is trusted for long stretches; under fatigue or forced change, what-ifs arrive suddenly and totally — every unfamiliar option at once, all ending badly, in a voice that does not sound like them. This is Quenk's grip, seen from inside.",provenance:"quenk"},"ne.slot.opposing":{example:"An INTJ answers a brainstorm with fourteen deliberately disposable ideas and one raised eyebrow.",figure:"Below the waterline, a thicket grown overnight to block a path.",mechanism:"The fifth seat opens the shadow — the four positions a person runs rarely, and mostly without noticing. Here Ne wakes combative: when somebody's scatter of options threatens the single long read, rival possibilities get sprayed not to explore them but to demonstrate that options are cheap — and that the cheapness is the argument against them.",provenance:"beebe"},"ne.slot.tertiary":{example:"An ESFJ produces three genuinely clever variants for the fundraiser, then rules all further variants out of order.",figure:"A half-size tree that blooms on weekends.",mechanism:"In the third seat, divergence shows up in bursts — the offsite with sticky notes, the renovation scheme at midnight — real ability, trusted unevenly, and dropped fast when the plan reasserts itself. It steadies with age, mostly by being let out on purpose instead of by accident.",provenance:"grant"},"ne.slot.trickster":{example:'Asked "what if the supplier falls through?", an ISTP says "what if the building floods?" and considers the matter closed.',figure:"The tree grows one branch at a time, at right angles nobody predicted.",mechanism:"In the seventh seat, hypotheticals register as a rigged game. The plausible what-if is either invisible or answered with one so outlandish it discredits the exercise — and the person genuinely cannot tell which of the two just happened. No malice; no report.",provenance:"beebe"},"ne.zoneA.canvasAria":"Interactive visual representation of Extraverted Intuition as a divergence engine: stimuli enter through an open ring and erupt into a branching tree of possibilities, with sparks escaping outward past the boundary. Sweep or drag anywhere to grow new branches toward the pointer","ne.zoneB.heading":"The Eight Faces of Ne","ne.zoneB.lede":"The canvas draws Ne as a branching tree: one stimulus in, many possibilities out. Where Ne sits in a person's stack — the fixed order their eight functions come in — changes how it branches. Click a position to see the change, from the dominant's omnidirectional bloom to the demon's hostile what-ifs, and watch the live-branch count: it tells the story before the caption does. Drag the maturity slider to watch the lower seats gain fidelity with age.","ne.zoneB.railAria":"Stack positions for Ne","ne.zoneC.heading":"What Feeds Into Ne?","ne.zoneC.lede":"Ne gathers; it does not judge. Extraverted perception is fed by introverted judgment, so its real partners are the inner judges — Ti and Fi, the functions that decide which branches deserve to live. Click a feeder to watch what grows.","ne.zoneC.unstableDefault":"Unstable coupling: perception feeding perception, with nothing judging either.","ne.zoneD.canvasAria":"The Ne divergence engine: stimuli enter an open aperture and branch into a living tree of possibilities; scenarios cross-pollinate, prune, scatter, riff with, or confine it. Sweep or drag to grow branches by hand","ne.zoneD.heading":"The Divergence Engine","ne.zoneD.kicker":"Zone D · the divergence engine","ne.zoneD.lede":"Ne branches one stimulus into many possibilities, in public, at speed. This lab exposes the divergence engine's live state — stress, pleasure, breadth, open threads — and five ways a day can treat it. Trigger a scenario and watch the telemetry answer.","ne.zoneD.ledeHintCoarse":"Drag a finger across the chamber at any time to branch by hand.","ne.zoneD.ledeHintFine":"Sweep the chamber at any time to branch by hand.","ne.zoneE.lede":"Patterns from the wild — how Ne shows up in daily life."};x(S);function j(){const a={fn:i("--c-accent"),n:i("--c-n"),s:i("--c-s"),f:i("--c-f"),pos:[i("--pos-1"),i("--pos-2"),i("--pos-3"),i("--pos-4")],sh:i("--pos-sh"),warn:i("--warn"),crit:i("--crit"),ink:i("--ink"),ink2:i("--ink-2"),muted:i("--muted"),grid:i("--grid"),axis:i("--axis"),surface:i("--surface")},r=e=>({name:t(`site.position.${e}.name`),ord:t(`site.position.${e}.ord`)}),u=[{key:"dominant",...r("dominant"),types:"ENTP · ENFP",shadow:!1,series:0,params:{scale:1,fidelity:.95,latency:0,noise:0,duty:1,control:1,contrary:0},copy:n("ne.slot.dominant")},{key:"auxiliary",...r("auxiliary"),types:"INTP · INFP",shadow:!1,series:1,params:{scale:.8,fidelity:.85,latency:80,noise:.05,duty:.85,control:.9,contrary:0},copy:n("ne.slot.auxiliary")},{key:"tertiary",...r("tertiary"),types:"ESTJ · ESFJ",shadow:!1,series:2,params:{scale:.55,fidelity:.6,latency:250,noise:.2,duty:.5,control:.6,contrary:0},copy:n("ne.slot.tertiary")},{key:"inferior",...r("inferior"),types:"ISTJ · ISFJ",shadow:!1,series:3,params:{scale:.4,fidelity:.35,latency:700,noise:.45,duty:.25,control:.35,contrary:.1},copy:n("ne.slot.inferior")},{key:"opposing",...r("opposing"),types:"INTJ · INFJ",shadow:!0,series:4,params:{scale:.46,fidelity:.42,latency:600,noise:.5,duty:.45,control:.4,contrary:.25},copy:n("ne.slot.opposing")},{key:"critical",...r("critical"),types:"ENTJ · ENFJ",shadow:!0,series:4,params:{scale:.44,fidelity:.35,latency:900,noise:.55,duty:.35,control:.3,contrary:.35},copy:n("ne.slot.critical")},{key:"trickster",...r("trickster"),types:"ISTP · ISFP",shadow:!0,series:4,params:{scale:.42,fidelity:.28,latency:1200,noise:.6,duty:.3,control:.2,contrary:.55},copy:n("ne.slot.trickster")},{key:"demon",...r("demon"),types:"ESTP · ESFP",shadow:!0,series:4,params:{scale:.4,fidelity:.2,latency:1500,noise:.65,duty:.22,control:.12,contrary:.65},copy:n("ne.slot.demon")}],f={endurance:{w:.8,why:t("ne.character.endurance.why")},precision:{w:.55,why:t("ne.character.precision.why")},speed:{w:.95,why:t("ne.character.speed.why")},control:{w:.6,why:t("ne.character.control.why")},awareness:{w:.75,why:t("ne.character.awareness.why")}},g=[{key:"ti",name:"Ti",color:"#4fc9e0",canonical:!0,cfg:{rate:.28,weight:.95,speed:.55,depth:.9,spread:.5,persistence:.85,filter:.5},copy:n("ne.feeder.ti")},{key:"fi",name:"Fi",color:"#f56a8c",canonical:!0,cfg:{rate:.3,weight:.85,speed:.5,depth:.65,spread:.7,persistence:.95,valued:.45},copy:n("ne.feeder.fi")},{key:"si",name:"Si",color:a.s,canonical:!1,unstable:!0,cfg:{rate:.95,weight:.25,speed:.9,depth:.3,spread:.35,persistence:.3,starve:!0,curl:.8},copy:n("ne.feeder.si")},{key:"te",name:"Te",color:"#17d4ef",canonical:!1,cfg:{rate:.5,weight:.7,speed:.7,depth:.45,spread:.95,persistence:.3,loop:!0},copy:n("ne.feeder.te")},{key:"fe",name:"Fe",color:"#f9748f",canonical:!1,cfg:{rate:.55,weight:.6,speed:.7,depth:.4,spread:1,persistence:.28,loop:!0},copy:n("ne.feeder.fe")}];function m(e){const l=12.2*(e/60),h=e%9/9,c=1.5*Math.max(0,1-Math.abs(h-.08)*7);return Math.max(0,l-c)}function b(e){const l=19.5*Math.pow(e/60,1.24);let h=0;for(const[d,N]of[[11,9],[33,10],[58,12],[88,9]])e>=d&&(h+=N*p((e-d)/1.8,0,1));const c=e<2?0:1.7*Math.sin(e*.85)+1.3*Math.sin(e*2.2+.9);return p(l+h+c,0,100)}const s=[{key:"dom",label:t("site.position.dominant.name"),color:a.pos[0],f:m},{key:"aux",label:t("site.position.auxiliary.name"),color:a.pos[1],f:e=>20.5*Math.pow(e/60,1.06)},{key:"tert",label:t("site.position.tertiary.name"),color:a.pos[2],f:e=>29*Math.pow(e/60,1.4)},{key:"inf",label:t("site.position.inferior.name"),color:a.pos[3],f:e=>Math.min(100,83*Math.pow(e/60,1.9))},{key:"sh",label:t("site.position.shadow.name"),color:a.sh,f:b}],y=60*Math.pow(100/83,1/1.9),w=[{label:t("site.position.dominant.name"),v:1,color:a.pos[0],series:0},{label:t("site.position.auxiliary.name"),v:1.5,color:a.pos[1],series:1},{label:t("site.position.tertiary.name"),v:2.5,color:a.pos[2],series:2},{label:t("site.position.inferior.name"),v:4,color:a.pos[3],series:3},{label:t("site.position.shadow.name"),v:4.5,color:a.sh,band:[3,6],series:4}],v=[{label:t("site.position.dominant.name"),color:a.pos[0],note:t("ne.energy.recovery.dominant"),f:e=>e<=30?100-s[0].f(e):o(0)+(100-o(0))*(1-Math.exp(-(e-30)/6.5))},{label:t("site.position.auxiliary.name"),color:a.pos[1],note:t("ne.energy.recovery.auxiliary"),f:e=>e<=30?100-s[1].f(e):o(1)+(100-o(1))*(1-Math.exp(-(e-30)/10))},{label:t("site.position.tertiary.name"),color:a.pos[2],note:t("ne.energy.recovery.tertiary"),f:e=>e<=30?100-s[2].f(e):o(2)+(100-o(2))*(1-Math.exp(-(e-30)/16))},{label:t("site.position.inferior.name"),color:a.pos[3],note:t("ne.energy.recovery.inferior"),f:e=>e<=30?100-s[3].f(e):e<60?o(3):o(3)+(100-o(3))*(1-Math.exp(-(e-60)/20))},{label:t("site.position.shadow.name"),color:a.sh,note:t("ne.energy.recovery.shadow"),f:e=>e<=30?100-s[4].f(e):o(4)+(92-o(4))*(1-Math.exp(-(e-30)/25))}];function o(e){return 100-s[e].f(30)}const k={buttons:[{id:"btnGraft",key:"graft",color:a.fn,impact:{stress:-.35,pleasure:.9},followMs:5800},{id:"btnPrune",key:"prune",color:a.crit,impact:{stress:.95,pleasure:-.75},followMs:6400},{id:"btnScatter",key:"scatter",color:a.warn,impact:{stress:.3,pleasure:.7},followMs:6800},{id:"btnRiff",key:"riff",color:"#4fc9e0",impact:{stress:-.7,pleasure:.8},followMs:6600},{id:"btnConfine",key:"confine",color:a.s,impact:{stress:.22,pleasure:-.55},followMs:7200}],states:{flow:{label:t("ne.lab.state.flow"),color:"#17c964"},equilibrium:{label:t("ne.lab.state.equilibrium"),color:a.fn},scattered:{label:t("ne.lab.state.scattered"),color:a.warn},pruned:{label:t("ne.lab.state.pruned"),color:a.crit},starved:{label:t("ne.lab.state.starved"),color:a.sh}},narrations:{graft:n("ne.lab.narration.graft"),graft2:n("ne.lab.narration.graft2"),prune:n("ne.lab.narration.prune"),prune2:n("ne.lab.narration.prune2"),scatter:n("ne.lab.narration.scatter"),scatter2:n("ne.lab.narration.scatter2"),riff:n("ne.lab.narration.riff"),riff2:n("ne.lab.narration.riff2"),confine:n("ne.lab.narration.confine"),confine2:n("ne.lab.narration.confine2"),hover:t("ne.lab.narration.hover")}},T={mirror:{label:"Ne",counterpart:"Ni",counterpartColor:"#8257f0",copy:n("ne.fieldNotes.mirror"),link:{href:"/ni/",label:t("ne.fieldNotes.mirrorLink")}},vignettes:[n("ne.fieldNotes.vignette.whiteboard"),n("ne.fieldNotes.vignette.loop"),n("ne.fieldNotes.vignette.grip"),n("ne.fieldNotes.vignette.fencedMeadow"),n("ne.fieldNotes.vignette.neverFinish"),n("ne.fieldNotes.vignette.mistakenForSe"),n("ne.fieldNotes.vignette.signedContract")]};return{COL:a,SLOTS:u,CHARACTER:f,FEEDERS:g,SERIES:s,GRIP_T:y,COSTS:w,RECOVERY:v,LAB:k,ZONE_F:T}}export{j as l};
